"""Cubase-oriented Standard MIDI File (SMF) preflight and loss-audited export.

The exporter uses mido's event representation rather than pretty_midi's
higher-level reconstruction so CC, pitch bend, SysEx, text and marker events
survive wherever the SMF supports them. Cubase itself is not automated here.
"""
from __future__ import annotations

from collections import Counter, defaultdict, deque
from hashlib import sha256
import json
from pathlib import Path
import os
import tempfile

import mido

GLOBAL_META = frozenset(("set_tempo", "time_signature", "key_signature"))
MIN_PPQ = 24
MAX_PPQ = 960


def _read(path: str | Path) -> mido.MidiFile:
    source = Path(path)
    if source.suffix.lower() not in (".mid", ".midi"):
        raise ValueError("Standard MIDI file must end with .mid or .midi")
    if not source.is_file():
        raise FileNotFoundError(source)
    midi = mido.MidiFile(str(source))
    if midi.type not in (0, 1):
        raise ValueError("SMF type 2 is not supported by the Cubase interchange profile")
    if midi.ticks_per_beat <= 0:
        raise ValueError("SMF must have positive PPQ")
    return midi


def _events(track: mido.MidiTrack):
    absolute = 0
    for msg in track:
        absolute += msg.time
        if msg.type != "end_of_track":
            yield absolute, msg


def _scale(tick: int, src_ppq: int, dst_ppq: int) -> int:
    # All SMF ticks are nonnegative; round half up for deterministic MIDI timing.
    return (tick * dst_ppq * 2 + src_ppq) // (2 * src_ppq)


def _signature(midi: mido.MidiFile, dest_ppq: int) -> Counter:
    events = Counter()
    for track in midi.tracks:
        for tick, msg in _events(track):
            item = msg.dict()
            item.pop("time", None)
            events[(_scale(tick, midi.ticks_per_beat, dest_ppq),
                    json.dumps(item, sort_keys=True, ensure_ascii=False))] += 1
    return events


def _count_note_ons(midi: mido.MidiFile) -> int:
    return sum(
        1 for track in midi.tracks for msg in track
        if msg.type == "note_on" and msg.velocity > 0
    )


def _check_short_notes(midi: mido.MidiFile, dst_ppq: int):
    """Reject resolutions that collapse positive-duration notes into zero ticks."""
    for track in midi.tracks:
        starts = defaultdict(deque)
        for tick, msg in _events(track):
            if msg.type == "note_on" and msg.velocity > 0:
                starts[(msg.channel, msg.note)].append(tick)
            elif msg.type == "note_off" or (
                msg.type == "note_on" and msg.velocity == 0
            ):
                q = starts[(msg.channel, msg.note)]
                if q:
                    started = q.popleft()
                    if tick > started and _scale(tick, midi.ticks_per_beat, dst_ppq) <= (
                        _scale(started, midi.ticks_per_beat, dst_ppq)
                    ):
                        raise ValueError(
                            "PPQ conversion would collapse a positive-duration note; "
                            "choose a higher --ppq or preserve original timing"
                        )


def inspect_smf(path: str | Path) -> dict:
    midi = _read(path)
    counts = Counter(msg.type for track in midi.tracks for msg in track)
    misplaced = sum(
        1 for track in midi.tracks[1:] for msg in track
        if msg.is_meta and msg.type in GLOBAL_META
    )
    warnings = []
    if midi.type == 0:
        warnings.append("Type 0 combines all MIDI channels; export can split channels into Type 1.")
    if misplaced:
        warnings.append(
            f"{misplaced} global tempo/meter/key events are outside track 0; "
            "Cubase Type 1 export will relocate them to the conductor track."
        )
    if midi.ticks_per_beat > MAX_PPQ:
        warnings.append(
            f"Original PPQ {midi.ticks_per_beat} exceeds the optional "
            "24..960 export profile; conversion can quantize fine timing."
        )
    if counts["sysex"]:
        warnings.append("SysEx data is preserved in the SMF, but hardware/plugin behavior is not guaranteed.")
    if midi.type == 1 and len(midi.tracks) == 1:
        warnings.append("Type 1 has one track; Cubase multitrack arrangement not present.")
    return {
        "input": str(Path(path).resolve()),
        "sha256": sha256(Path(path).read_bytes()).hexdigest(),
        "type": midi.type,
        "ppq": midi.ticks_per_beat,
        "tracks": len(midi.tracks),
        "notes_on": _count_note_ons(midi),
        "tempo_events": counts["set_tempo"],
        "meter_events": counts["time_signature"],
        "key_events": counts["key_signature"],
        "control_changes": counts["control_change"],
        "pitch_bends": counts["pitchwheel"],
        "sysex_events": counts["sysex"],
        "nonconductor_global_meta": misplaced,
        "warnings": warnings,
    }


def _pack(events: list[tuple[int, mido.Message]], end_tick: int) -> mido.MidiTrack:
    track = mido.MidiTrack()
    before = 0
    for absolute, message in sorted(events, key=lambda x: x[0]):
        if absolute < before:
            raise ValueError("Negative event delta after normalization")
        track.append(message.copy(time=absolute - before))
        before = absolute
    track.append(mido.MetaMessage("end_of_track", time=max(0, end_tick - before)))
    return track


def _make_type1(midi: mido.MidiFile, ppq: int) -> mido.MidiFile:
    conductor: list[tuple[int, mido.Message]] = []
    tracks: list[list[tuple[int, mido.Message]]] = []
    ends: list[int] = []
    if midi.type == 0:
        per_channel: dict[int, list[tuple[int, mido.Message]]] = {}
        channel_ends = {}
        total_tick = 0
        for tick, msg in _events(midi.tracks[0]):
            new_tick = _scale(tick, midi.ticks_per_beat, ppq)
            total_tick = max(total_tick, new_tick)
            if hasattr(msg, "channel"):
                per_channel.setdefault(msg.channel, []).append((new_tick, msg))
                channel_ends[msg.channel] = new_tick
            else:
                conductor.append((new_tick, msg))
        for channel in sorted(per_channel):
            tracks.append(per_channel[channel])
            ends.append(channel_ends[channel])
        conductor_end = total_tick
    else:
        conductor_end = 0
        for index, original in enumerate(midi.tracks):
            musical: list[tuple[int, mido.Message]] = []
            end = 0
            for tick, msg in _events(original):
                new_tick = _scale(tick, midi.ticks_per_beat, ppq)
                end = max(end, new_tick)
                if msg.is_meta and msg.type in GLOBAL_META:
                    conductor.append((new_tick, msg))
                    conductor_end = max(conductor_end, new_tick)
                elif index == 0 and msg.is_meta:
                    conductor.append((new_tick, msg))
                    conductor_end = max(conductor_end, new_tick)
                else:
                    musical.append((new_tick, msg))
            if musical:
                tracks.append(musical)
                ends.append(end)
    out = mido.MidiFile(type=1, ticks_per_beat=ppq)
    out.tracks.append(_pack(conductor, conductor_end))
    for events, end in zip(tracks, ends):
        out.tracks.append(_pack(events, end))
    return out


def prepare_smf(source: str | Path, destination: str | Path, *,
                ppq: int = 480) -> dict:
    """Export Type 1 conductor+multitrack SMF, never replacing source/existing files."""
    src = Path(source).expanduser().resolve()
    target = Path(destination).expanduser().resolve()
    if src == target:
        raise ValueError("Source and destination must differ")
    if not isinstance(ppq, int) or isinstance(ppq, bool) or not MIN_PPQ <= ppq <= MAX_PPQ:
        raise ValueError("Export PPQ must be 24..960")
    if target.suffix.lower() not in (".mid", ".midi") or not target.parent.is_dir():
        raise ValueError("Output must be .mid/.midi in an existing directory")
    if target.exists():
        raise FileExistsError(f"Refusing to overwrite {target}")
    midi = _read(src)
    _check_short_notes(midi, ppq)
    prepared = _make_type1(midi, ppq)
    if _signature(midi, ppq) != _signature(prepared, ppq):
        raise ValueError("Export changed one or more MIDI event values or tick positions")
    fd, staging = tempfile.mkstemp(
        prefix=f".{target.name}.", suffix=".tmp", dir=target.parent)
    os.close(fd)
    staged = Path(staging)
    try:
        prepared.save(str(staged))
        reopened = _read_mido_temp(staged)
        if _signature(midi, ppq) != _signature(reopened, ppq):
            raise ValueError("Serialized SMF roundtrip changed MIDI event content")
        try:
            os.link(staged, target)
        except FileExistsError as exc:
            raise FileExistsError(f"Refusing to overwrite {target}") from exc
    finally:
        staged.unlink(missing_ok=True)
    return {
        "source": str(src),
        "output": str(target),
        "type": 1,
        "ppq_original": midi.ticks_per_beat,
        "ppq_export": ppq,
        "tracks": len(prepared.tracks),
        "note_events": _count_note_ons(prepared),
        "all_midi_events_preserved_after_tick_rescale": True,
        "source_sha256": sha256(src.read_bytes()).hexdigest(),
        "output_sha256": sha256(target.read_bytes()).hexdigest(),
        "timing_quantization_possible": midi.ticks_per_beat != ppq,
        "cubase_application_import_verified": False,
    }


def _read_mido_temp(path: Path) -> mido.MidiFile:
    return mido.MidiFile(str(path))


def compare_smf(reference: str | Path, returned: str | Path) -> dict:
    """Compare Cubase-exported result semantically, in original PPQ units."""
    before = _read(reference)
    after = _read(returned)
    # Canonical common PPQ is the product (not rounded fraction) so events
    # with differing PPQ have an exact tick-position comparison.
    common_ppq = before.ticks_per_beat * after.ticks_per_beat
    events_before = _signature(before, common_ppq)
    events_after = _signature(after, common_ppq)
    missing = events_before - events_after
    added = events_after - events_before
    return {
        "source": str(Path(reference).resolve()),
        "roundtrip": str(Path(returned).resolve()),
        "reference_tracks": len(before.tracks),
        "returned_tracks": len(after.tracks),
        "note_on_reference": _count_note_ons(before),
        "note_on_returned": _count_note_ons(after),
        "exact_event_match": not missing and not added,
        "missing_events": sum(missing.values()),
        "added_events": sum(added.values()),
        "warning": (
            "Strict comparison includes metadata, track names, program/CC and "
            "tempo events. Cubase may intentionally transform them based on import "
            "options; inspect its preferences and exported file."
        ),
        "cubase_import_verified": False,
    }

"""Fast, weight-free drum-event transcription baseline for *isolated drum* WAVs.

DSP detection + conservative spectral heuristics; NOT a neural drum classifier.
No model downloads or sample templates. Emits only three GM drum voices:
36 kick, 38 snare, 42 closed hi-hat. No invented cymbal/tom classes.
"""
from __future__ import annotations

import math
from pathlib import Path

import numpy as np
import pretty_midi
from scipy import signal
from scipy.io import wavfile

TARGET_SR = 22050
FFT_SIZE = 1024
HOP = 256
GM_PITCH = {"kick": 36, "snare": 38, "hat": 42}
FLUX_BANDS = {
    "kick": (35, 180),
    "snare": (300, 4000),
    "hat": (5200, 10500),
}
POWER_BANDS = {
    "low": (35, 180),
    "mid": (180, 5200),
    "high": (5200, 10500),
}


def read_audio(path: Path) -> tuple[np.ndarray, int]:
    """Read finite mono/stereo WAV; resample only, preserve the original zero."""
    sr, raw = wavfile.read(str(path))
    if sr <= 0 or raw.size == 0:
        raise ValueError(f"Drum WAV is empty or invalid: {path}")
    if raw.ndim not in (1, 2):
        raise ValueError("Only mono and multichannel WAV are supported.")
    if raw.dtype.kind == "u" and raw.dtype.itemsize == 1:
        samples = (raw.astype(np.float32) - 128.0) / 128.0
    elif raw.dtype.kind in "iu":
        # scipy stores signed 24-bit PCM in int32, left-justified.
        samples = raw.astype(np.float32) / float(2 ** (raw.dtype.itemsize * 8 - 1))
    elif raw.dtype.kind == "f":
        samples = raw.astype(np.float32)
    else:
        raise ValueError(f"Unsupported WAV sample format: {raw.dtype}")
    if samples.ndim == 2:
        samples = np.mean(samples, axis=1, dtype=np.float32)
    if not np.isfinite(samples).all():
        raise ValueError("Drum WAV contains nonfinite audio.")
    if sr != TARGET_SR:
        gcd = math.gcd(sr, TARGET_SR)
        samples = signal.resample_poly(samples, TARGET_SR // gcd, sr // gcd).astype(np.float32)
    return np.clip(samples, -1.0, 1.0), TARGET_SR


def _power_shares(magnitude: np.ndarray, freq: np.ndarray, i: int) -> tuple[float, float, float]:
    # Use frames around the transient, not the entire decaying tail.
    sample = np.mean(magnitude[:, i:min(i + 4, magnitude.shape[1])] ** 2, axis=1)
    parts = []
    for low, high in POWER_BANDS.values():
        parts.append(float(np.sum(sample[(freq >= low) & (freq < high)])))
    total = sum(parts)
    return tuple(v / total if total > 1e-14 else 0.0 for v in parts)


def _accept(kind: str, shares: tuple[float, float, float]) -> bool:
    low, mid, high = shares
    if kind == "kick":
        return low >= 0.38 and low >= mid
    if kind == "snare":
        return mid >= 0.43 and mid >= 1.8 * high
    if kind == "hat":
        # Hat can coexist with a loud kick; check high-to-mid ratio too.
        return high >= 0.12 and high >= 2.5 * mid
    return False


def transcribe_drum_wav(
    path: Path,
    *,
    tempo: float = 120.0,
    min_peak_fraction: float = 0.09,
) -> tuple[pretty_midi.PrettyMIDI, dict]:
    """Return drum MIDI and diagnostics, with all event times in WAV seconds.

    This is a baseline for clean drum stems, not a validated production model.
    """
    if not (20 <= tempo <= 400):
        raise ValueError("Drum MIDI grid tempo must be 20..400 BPM")
    if not (0.01 <= min_peak_fraction <= 0.8):
        raise ValueError("min_peak_fraction must be 0.01..0.8")
    audio, sr = read_audio(Path(path))
    midi = pretty_midi.PrettyMIDI(initial_tempo=tempo, resolution=960)
    track = pretty_midi.Instrument(program=0, is_drum=True, name=f"drums | {Path(path).stem}")
    midi.instruments.append(track)
    duration = len(audio) / sr
    if np.max(np.abs(audio)) < 0.003:
        return midi, {"engine": "drum_dsp_v1", "counts": dict.fromkeys(GM_PITCH, 0),
                      "detected": 0, "ignored_candidates": 0, "duration_seconds": duration}

    frequencies, times, stft = signal.stft(
        audio, fs=sr, window="hann", nperseg=FFT_SIZE, noverlap=FFT_SIZE - HOP,
        boundary="zeros", padded=True,
    )
    magnitude = np.abs(stft)
    events = []
    ignored = 0

    for kind, (lo, hi) in FLUX_BANDS.items():
        band = magnitude[(frequencies >= lo) & (frequencies < hi)]
        if band.size == 0:
            continue
        flux = np.r_[0.0, np.sum(np.maximum(0.0, np.diff(band, axis=1)), axis=0)]
        nonzero = flux[flux > 0]
        if not len(nonzero):
            continue
        threshold = max(
            float(np.max(flux)) * min_peak_fraction,
            float(np.percentile(nonzero, 60)) * 3.0,
        )
        peaks, _ = signal.find_peaks(
            flux, height=threshold, prominence=threshold * 0.5,
            distance=max(1, round(0.05 * sr / HOP)),
        )
        candidates = []
        for i in peaks:
            onset = float(times[i])
            if onset > duration + HOP / sr:
                continue
            # Classify on the transient's spectral profile, not the onset's
            # nominal frequency-band label alone.
            shares = _power_shares(magnitude, frequencies, int(i))
            if not _accept(kind, shares):
                ignored += 1
                continue
            # Exclude tiny events amid strong background/silence.
            start = max(0, round(onset * sr))
            stop = min(len(audio), start + round(0.07 * sr))
            rms = float(np.sqrt(np.mean(audio[start:stop] ** 2))) if stop > start else 0.0
            if rms < 0.001:
                ignored += 1
                continue
            candidates.append((max(0.0, onset), rms))

        # The same event may produce several adjacent spectral peaks.
        for onset, rms in sorted(candidates):
            if events and any(
                e[0] == kind and abs(e[1] - onset) < 0.045
                for e in events[-8:]
            ):
                ignored += 1
            else:
                events.append((kind, onset, rms))

    events.sort(key=lambda item: (item[1], GM_PITCH[item[0]]))
    rms_reference = float(np.percentile([e[2] for e in events], 90)) if events else 0.0
    counts = {kind: 0 for kind in GM_PITCH}
    for kind, onset, rms in events:
        counts[kind] += 1
        velocity = int(np.clip(round(105 * math.sqrt(rms / max(rms_reference, 1e-9))), 20, 127))
        track.notes.append(pretty_midi.Note(
            velocity=velocity,
            pitch=GM_PITCH[kind],
            start=onset,
            end=onset + 0.10,
        ))
    return midi, {
        "engine": "drum_dsp_v1",
        "counts": counts,
        "detected": len(events),
        "ignored_candidates": ignored,
        "duration_seconds": round(duration, 6),
        "caveat": "Kick/snare/closed-hat baseline only; onset/spectral heuristic may miss "
                  "ghost notes, classify cymbals/snare incorrectly, and cannot identify "
                  "tom/open-hat/ride. No beats quantized or timeline shifted.",
    }

"""Validated MIDI I/O with crash-safe atomic writes."""

from __future__ import annotations

import os
from pathlib import Path
import tempfile

import pretty_midi


def read_midi(path: str | Path) -> pretty_midi.PrettyMIDI:
    source = Path(path)
    if source.suffix.lower() not in {".mid", ".midi"}:
        raise ValueError("Input must be a .mid or .midi file.")
    if not source.is_file():
        raise FileNotFoundError(source)
    return pretty_midi.PrettyMIDI(str(source))


def write_midi(
    midi: pretty_midi.PrettyMIDI, path: str | Path, *, overwrite: bool = False
) -> Path:
    """Serialize to a sibling temporary file and publish only once complete.

    For an existing file, an exception during serialization never truncates
    the original. In no-overwrite mode, an atomic hard-link operation refuses
    a target created concurrently, preventing accidental replacement.
    """
    target = Path(path)
    if target.suffix.lower() not in {".mid", ".midi"}:
        raise ValueError("Output must use .mid or .midi.")
    if not target.parent.is_dir():
        raise FileNotFoundError(f"Output directory does not exist: {target.parent}")
    if target.exists() and not overwrite:
        raise FileExistsError(f"Refusing to overwrite {target}; use --overwrite.")

    fd, temp_name = tempfile.mkstemp(
        prefix=f".{target.name}.", suffix=".tmp", dir=target.parent
    )
    os.close(fd)
    staged = Path(temp_name)
    try:
        midi.write(str(staged))
        if overwrite:
            os.replace(staged, target)
        else:
            try:
                os.link(staged, target)
            except FileExistsError as exc:
                raise FileExistsError(
                    f"Refusing to overwrite {target}; use --overwrite."
                ) from exc
        return target
    finally:
        staged.unlink(missing_ok=True)

"""Offline model-process integration; no weights downloaded or vendored."""
from __future__ import annotations
from copy import deepcopy
from dataclasses import dataclass
import json
import math
import os
from pathlib import Path
import subprocess
import tempfile

import pretty_midi
from .io import read_midi, write_midi
from .review_engine import create_proposal

@dataclass(frozen=True)
class GenerationReport:
    model: str
    candidate: Path
    tracks: int
    notes: int
    source: Path | None
    manifest: Path | None
    locked: tuple[int, ...]
    warnings: tuple[str, ...]

    def as_dict(self):
        return {
            "model": self.model, "candidate": str(self.candidate),
            "tracks": self.tracks, "notes": self.notes,
            "source": str(self.source) if self.source else None,
            "manifest": str(self.manifest) if self.manifest else None,
            "locked_tracks": list(self.locked), "warnings": list(self.warnings),
        }

def _runner_script(model):
    return Path(__file__).parent / "model_runners" / (model + "_runner.py")

def _file(value, label):
    p = Path(value).expanduser().resolve(strict=True)
    if not p.is_file():
        raise ValueError(f"{label} must be a file: {p}")
    return p

def _dir(value, label):
    p = Path(value).expanduser().resolve(strict=True)
    if not p.is_dir():
        raise ValueError(f"{label} must be a directory: {p}")
    return p

def append_generated_tracks(source: pretty_midi.PrettyMIDI,
                            generated: pretty_midi.PrettyMIDI) -> pretty_midi.PrettyMIDI:
    """Append model notes using quarter-note alignment; keep source tracks/maps untouched."""
    result = deepcopy(source)
    def translate(seconds):
        tick = generated.time_to_tick(float(seconds))
        return float(source.tick_to_time(round(tick * source.resolution / generated.resolution)))
    for instrument in generated.instruments:
        if not instrument.notes:
            continue
        track = deepcopy(instrument)
        track.name = "MIDIVOLT AI | " + (instrument.name or
            pretty_midi.program_to_instrument_name(instrument.program))
        for note in track.notes:
            note.start, note.end = translate(note.start), translate(note.end)
            if note.end <= note.start:
                raise ValueError("Model note has invalid duration after alignment")
        for cc in track.control_changes:
            cc.time = translate(cc.time)
        for bend in track.pitch_bends:
            bend.time = translate(bend.time)
        result.instruments.append(track)
    if len(result.instruments) == len(source.instruments):
        raise ValueError("Model returned no notes to append")
    return result

def generate_candidate(*, model, python_executable, checkout, checkpoint,
                       output_path, source_path=None, manifest_path=None,
                       locked_tracks=None, prompt=None, vocab_path=None,
                       t5_dir=None, melody_program=None, seconds=None,
                       top_p=0.98, temperature=0.9, max_tokens=2000,
                       timeout=1200.0, seed=None):
    """Run a separately installed model, produce MIDI, and optionally a guarded proposal."""
    if model not in ("text2midi", "anticipation"):
        raise ValueError("Unsupported model")
    if not math.isfinite(timeout) or not 1 <= timeout <= 7200:
        raise ValueError("--timeout must be 1..7200 seconds")
    if seed is not None and (type(seed) is not int or not 0 <= seed < 2**31):
        raise ValueError("--seed must be a nonnegative 31-bit integer")
    exe = _file(python_executable, "Model Python interpreter")
    root = _dir(checkout, "Upstream model checkout")
    if model == "text2midi":
        if not (root / "model" / "transformer_model.py").is_file():
            raise ValueError("Missing Text2midi model/transformer_model.py")
        if not isinstance(prompt, str) or not prompt.strip() or len(prompt) > 8192:
            raise ValueError("Text2midi requires --prompt (1..8192 chars)")
        if vocab_path is None or t5_dir is None:
            raise ValueError("Text2midi requires --vocab and local --t5-dir")
        vocab = _file(vocab_path, "Tokenizer vocabulary")
        t5 = _dir(t5_dir, "T5 tokenizer cache directory")
        checkpoint = _file(checkpoint, "Text2midi checkpoint")
        if not math.isfinite(temperature) or not 0.1 <= temperature <= 2:
            raise ValueError("--temperature must be 0.1..2")
        if type(max_tokens) is not int or not 32 <= max_tokens <= 4096:
            raise ValueError("--max-tokens must be 32..4096")
    else:
        if not (root / "anticipation" / "sample.py").is_file():
            raise ValueError("Missing anticipation/sample.py")
        if source_path is None:
            raise ValueError("Anticipation requires --source")
        if type(melody_program) is not int or not 0 <= melody_program <= 127:
            raise ValueError("Anticipation requires --melody-program 0..127")
        if seconds is None or not math.isfinite(seconds) or not 0.5 <= seconds <= 120:
            raise ValueError("--seconds must be 0.5..120")
        if not math.isfinite(top_p) or not 0 < top_p <= 1:
            raise ValueError("--top-p must be (0,1]")
        checkpoint = _dir(checkpoint, "Anticipation model directory")
    src = _file(source_path, "Source MIDI") if source_path is not None else None
    dst = Path(output_path).expanduser().resolve()
    manifest = Path(manifest_path).expanduser().resolve() if manifest_path else None
    locked = list(locked_tracks or [])
    if not dst.parent.is_dir() or dst.suffix.lower() not in (".mid", ".midi"):
        raise ValueError("Candidate must be a .mid/.midi in an existing directory")
    if manifest and (src is None or not locked):
        raise ValueError("--manifest requires --source and --lock")
    if locked and (src is None or manifest is None):
        raise ValueError("--lock requires --source and --manifest")
    paths = [v for v in (src, dst, manifest) if v is not None]
    if len(set(paths)) != len(paths):
        raise ValueError("Input, candidate and manifest must differ")
    if any(p.exists() for p in (dst, manifest) if p is not None):
        raise FileExistsError("Output MIDI or manifest already exists")
    if manifest and (manifest.suffix.lower() != ".json" or not manifest.parent.is_dir()):
        raise ValueError("Manifest must be a new JSON file in an existing directory")
    source_midi = read_midi(src) if src else None
    if manifest and (len(set(locked)) != len(locked) or any(
            type(i) is not int or i < 0 or i >= len(source_midi.instruments)
            for i in locked)):
        raise ValueError("Lock indexes must exist and be unique")
    runner = _runner_script(model)
    if not runner.is_file():
        raise FileNotFoundError(runner)
    with tempfile.TemporaryDirectory(prefix="midivolt-inference-") as td:
        raw = Path(td) / "raw.mid"
        args = [str(exe), str(runner), "--checkout", str(root),
                "--checkpoint", str(checkpoint), "--out", str(raw)]
        if seed is not None:
            args += ["--seed", str(seed)]
        if model == "text2midi":
            args += ["--prompt", prompt, "--vocab", str(vocab),
                     "--t5-dir", str(t5), "--temperature", str(temperature),
                     "--max-tokens", str(max_tokens)]
        else:
            args += ["--source", str(src), "--melody-program", str(melody_program),
                     "--seconds", str(seconds), "--top-p", str(top_p)]
        env = os.environ.copy()
        env.update(HF_HUB_OFFLINE="1", TRANSFORMERS_OFFLINE="1",
                   HF_DATASETS_OFFLINE="1", TOKENIZERS_PARALLELISM="false")
        try:
            task = subprocess.run(args, cwd=root, env=env, shell=False,
                                  capture_output=True, text=True, errors="replace",
                                  timeout=timeout, check=False)
        except subprocess.TimeoutExpired as exc:
            raise RuntimeError(f"{model} inference timed out") from exc
        if task.returncode:
            diagnostic = (task.stderr or task.stdout or "no details")[-2000:]
            raise RuntimeError(f"{model} inference failed: {diagnostic}")
        if not raw.is_file():
            raise RuntimeError("Model produced no MIDI file")
        generated = read_midi(raw)
        if not any(inst.notes for inst in generated.instruments):
            raise ValueError("Model generated MIDI without notes")
        result = append_generated_tracks(source_midi, generated) if source_midi else generated
        write_midi(result, dst)
    if manifest:
        create_proposal(src, dst, manifest, locked_tracks=locked)
    return GenerationReport(
        model=model, candidate=dst, tracks=len(result.instruments),
        notes=sum(len(inst.notes) for inst in result.instruments),
        source=src, manifest=manifest, locked=tuple(locked),
        warnings=("Generated notes were aligned by musical beats, not acoustic similarity.",
                  "Original tracks and tempo map were preserved.") if src else (),
    )
